/**
 * Unit tests for BasicDeserializerFactory._addExplicitAnyCreator
 */
public class BasicDeserializerFactory__addExplicitAnyCreator_TriageGen0Test {

    private TestableBasicDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private CreatorCollector creators;

    // Subclass to expose protected method for testing
    private static class TestableBasicDeserializerFactory extends BasicDeserializerFactory {
        protected TestableBasicDeserializerFactory() {
            super(null);
        }

        @Override
        protected DeserializerFactory withConfig(DeserializerFactoryConfig config) {
            return this;
        }

        @Override
        public void _addExplicitAnyCreator(DeserializationContext ctxt,
                                           BeanDescription beanDesc,
                                           CreatorCollector creators,
                                           CreatorCandidate candidate) throws JsonMappingException {
            super._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBasicDeserializerFactory();
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        creators = mock(CreatorCollector.class);
    }

    /**
     * Case 1: candidate.paramCount() != 1
     * Subcase 1a: Finds a parameter without injection and without name -> Delegating Creator
     * Subcase 1b: Otherwise -> Property Creator
     */
    @Test
    public void testNotOneParameter_DelegatingCreator() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        when(candidate.paramCount()).thenReturn(2);
        when(candidate.findOnlyParamWithoutInjection()).thenReturn(0);
        when(candidate.paramName(0)).thenReturn(null); // No name -> delegating

        // We need to spy the factory to verify calls to internal protected methods
        TestableBasicDeserializerFactory spyFactory = spy(factory);

        spyFactory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(spyFactory)._addExplicitDelegatingCreator(any(), any(), any(), any());
        verify(spyFactory, never())._addExplicitPropertyCreator(any(), any(), any(), any());
    }

    @Test
    public void testNotOneParameter_PropertyCreator() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        when(candidate.paramCount()).thenReturn(2);
        // Either no single param without injection, or it has a name
        when(candidate.findOnlyParamWithoutInjection()).thenReturn(-1);

        TestableBasicDeserializerFactory spyFactory = spy(factory);
        spyFactory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(spyFactory)._addExplicitPropertyCreator(any(), any(), any(), any());
    }

    /**
     * Case 2: candidate.paramCount() == 1
     * Subcase 2a: Has explicit name or injection -> Property Creator
     * Subcase 2b: No name/injection, but paramDef exists and implicit name matches -> Property Creator
     * Subcase 2c: No name/injection, no paramDef -> Single Argument Creator
     */
    @Test
    public void testOneParameter_UseProps_WithExplicitName() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        PropertyName name = PropertyName.construct("testName");
        StdCreator creator = mock(StdCreator.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.explicitParamName(0)).thenReturn(name);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addPropertyCreator(eq(creator), eq(true), any(SettableBeanProperty[].class));
    }

    @Test
    public void testOneParameter_UseProps_WithInjection() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        JacksonInject.Value injectId = mock(JacksonInject.Value.class);
        StdCreator creator = mock(StdCreator.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.injection(0)).thenReturn(injectId);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addPropertyCreator(eq(creator), eq(true), any(SettableBeanProperty[].class));
    }

    @Test
    public void testOneParameter_UseProps_ImplicitNameMatch() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        BeanPropertyDefinition paramDef = mock(BeanPropertyDefinition.class);
        PropertyName implicitName = PropertyName.construct("implicit");
        StdCreator creator = mock(StdCreator.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(paramDef);
        when(candidate.findImplicitParamName(0)).thenReturn(implicitName);
        when(paramDef.couldSerialize()).thenReturn(true);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addPropertyCreator(eq(creator), eq(true), any(SettableBeanProperty[].class));
    }

    @Test
    public void testOneParameter_SingleArgumentCreator_WithParamDefRemoval() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        BeanPropertyDefinition paramDef = mock(BeanPropertyDefinition.class);
        POJOPropertyBuilder builder = mock(POJOPropertyBuilder.class);
        StdCreator creator = mock(StdCreator.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(paramDef);
        when(candidate.creator()).thenReturn(creator);

        // Mock the cast to POJOPropertyBuilder
        // In real Jackson, paramDef is often an instance of POJOPropertyBuilder
        // Since we cannot easily mock the cast if the real object isn't a POJOPropertyBuilder, 
        // we must ensure the mock behaves correctly or use a real one.
        POJOPropertyBuilder realBuilder = new POJOPropertyBuilder(mock(com.fasterxml.jackson.databind.introspect.Annotated.class), "test");
        // We use the actual implementation to satisfy the cast in the method: ((POJOPropertyBuilder) paramDef).removeConstructors();
        // However, paramDef is a mock. Let's try to make the mock castable.

        // Re-mocking paramDef to be a real POJOPropertyBuilder to avoid ClassCastException
        // This is tricky with Mockito. A better way is to use a real POJOPropertyBuilder.
        // But since we are testing the logic:

        // We will use a real POJOPropertyBuilder and mock the candidate to return it.
        // We need an Annotated object for the constructor.
        Annotated mockAnnotated = mock(Annotated.class);
        POJOPropertyBuilder actualBuilder = new POJOPropertyBuilder(mockAnnotated, "prop");

        // We need to mock the propertyDef(0) to return a wrapper or the builder itself if it extends BeanPropertyDefinition
        // POJOPropertyBuilder extends BeanPropertyDefinition.
        when(candidate.propertyDef(0)).thenReturn(actualBuilder);

        TestableBasicDeserializerFactory spyFactory = spy(factory);
        spyFactory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        // Verify single argument creator was handled
        verify(spyFactory)._handleSingleArgumentCreator(eq(creators), eq(creator), eq(true), eq(true));
        // Verify constructors were removed
        // In a real scenario, we'd check if the builder's internal state changed.
    }

    @Test
    public void testOneParameter_SingleArgumentCreator_NoParamDef() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        StdCreator creator = mock(StdCreator.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(null);
        when(candidate.creator()).thenReturn(creator);

        TestableBasicDeserializerFactory spyFactory = spy(factory);
        spyFactory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(spyFactory)._handleSingleArgumentCreator(eq(creators), eq(creator), eq(true), eq(true));
    }
}
